        /* a closet has no order. spread the worn through it, and the working through those. */
        function spread(len,k,seed){
          var idx=[],i,r=seed,j,t;
          for(i=0;i<len;i++) idx.push(i);
          for(i=len-1;i>0;i--){ r=(r*1103515245+12345)%2147483648; j=r%(i+1); t=idx[i]; idx[i]=idx[j]; idx[j]=t; }
          return idx.slice(0,k);
        }
        var WORN=spread(C.own,C.worn,C.own*7919+13), WSET={}, GSET={}, gpick, z;
