    function band(p,a,b,f){ f=f||.05; var inn=seg(p,a,a+f); return b>=1?inn:Math.min(inn,1-seg(p,b-f,b)); }
    function scene(sel,fn){ var el=RZ.one(sel); if(!el) return; el._fn=fn; el._p=-1; scenes.push(el); }
    /* a pin taller than its contents leaves empty ground under the last line. size it to fit. */
    function fitPins(){
      for(var i=0;i<scenes.length;i++){
        var pin=scenes[i].querySelector('.pin'); if(!pin) continue;
        var w=pin.firstElementChild; if(!w) continue;
        w.style.transform=''; pin.style.height='';
        if(RM) continue;
        var cs=getComputedStyle(pin);
        var avail=pin.clientHeight-(parseFloat(cs.paddingTop)||0)-(parseFloat(cs.paddingBottom)||0);
        var need=Math.max(w.offsetHeight,w.scrollHeight);
        if(avail>0&&need>avail){
          /* taller than the screen: scale to fit rather than clip the bottom off */
          var k=Math.max(.52,avail/need);
          w.style.transformOrigin='50% 50%';
          w.style.transform='scale('+k.toFixed(4)+')';
        }
      }
    }
    function tickS(){ raf=0;
      for(var i=0;i<liveS.length;i++){ var sc=liveS[i];
        var pinEl=sc.querySelector('.pin');
        var travel=sc.offsetHeight-(pinEl?pinEl.offsetHeight:window.innerHeight); if(travel<=0) continue;
        var p=clamp(-sc.getBoundingClientRect().top/travel);
        if(p===sc._p) continue; sc._p=p; sc._fn(sc,p); } }
    function reqS(){ if(!raf) raf=requestAnimationFrame(tickS); }
    document.addEventListener('visibilitychange',function(){ if(!document.hidden){ if(raf) cancelAnimationFrame(raf); raf=0; reqS(); } });

    /* ---------- scene one: being measured ---------- */
